connect.lines:
with record: http POST https://api.recordhost.com/offers | api=record | body=={offerId: offerId}
with check: http POST https://api.checkhost.com/run | api=check | body=={employeeId: employeeId}
with create: email createEmployeeAccount | authentication.simpleAuthenticationUsername==admin | authentication.simpleAuthenticationPassword={{secrets.MAIL_USER}} | imapHost==mail.recordhost.com | imapMessageIdDelete==offer.imapMessageId
with fetchuser: api slack GET https://slack.com/api/users.lookupByEmail | query: email==email
with notify: slack chat.postMessage | token={{secrets.SLACK_TOKEN}} | data.text== "Welcome " + createName + "! Your onboarding is complete." | data.channel==notifications
with update: http PUT https://api.orchost.com/employees | api=update | body=={managerId: managerId, employeeId: createName}
with payroll: http PUT https://api.payrollhost.com/employees | api=payroll | body=={startDate: startDate, id: createName}
with send: mail welcomeEmail | authentication.simpleAuthenticationUsername==noreply | authentication.simpleAuthenticationPassword={{secrets.MAIL_USER}} | smtpFrom==notifications | smtpTo==email | smtpSubject==Welcome aboard! | smtpBody==text"Welcome aboard, " + createName + ". Please check your email to complete the setup." | data.smtpHost==smtp.mailhost.com

